void E2ETests::olderWindowsUsesNightLightSettingsFallback(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>(true,true,false);FakePlatform *raw=fake.get();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("fallback.ini"))));controller.initialize();controller.settingsFor(QStringLiteral("fake-external")).isEink=true;MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();QVERIFY(!panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch")));auto *open=panel.findChild<QPushButton*>(QStringLiteral("night-light-button"));auto *recommendation=panel.findChild<QLabel*>(QStringLiteral("night-light-fallback-recommendation"));auto *path=panel.findChild<QLabel*>(QStringLiteral("night-light-settings-path"));QVERIFY(open);QVERIFY(recommendation);QVERIFY(path);QCOMPARE(path->text(),L("night.fallback.path"));QCOMPARE(panel.findChildren<QPushButton*>(QStringLiteral("night-light-button")).size(),1);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-night-light-settings-fallback.png")));open->click();QCOMPARE(raw->openedNightLight,1);controller.shutdown();}

void E2ETests::nightLightSwitchSynchronizesWithSystem(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();raw->nightDisabled=true;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("sync.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();auto *toggle=panel.findChild<QAbstractButton*>(QStringLiteral("disable-night-light-switch"));auto *status=panel.findChild<QLabel*>(QStringLiteral("disable-night-light-status"));auto *warning=panel.findChild<QLabel*>(QStringLiteral("night-light-warning"));QVERIFY(toggle);QVERIFY(status);QVERIFY(warning);QVERIFY(toggle->isChecked());QCOMPARE(status->text(),L("system.on"));QVERIFY(!warning->isVisible());raw->nightDisabled=false;controller.refreshNightLightState();QCoreApplication::processEvents();QVERIFY(!toggle->isChecked());QCOMPARE(status->text(),L("system.off"));QVERIFY(warning->isVisible());QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-night-light-warning.png")));raw->nightDisabled=true;controller.refreshNightLightState();QCoreApplication::processEvents();QVERIFY(toggle->isChecked());QCOMPARE(status->text(),L("system.on"));QVERIFY(!warning->isVisible());controller.shutdown();}

void E2ETests::welcomeFlowPersistsChoice(){QTemporaryDir dir;const QString path=dir.filePath(QStringLiteral("s.ini"));auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();QVERIFY(!controller.settings().trayDiscoveryShown);controller.setTrayDiscoveryShown(true);WelcomeDialog welcome(&controller);QVERIFY(welcome.windowFlags().testFlag(Qt::FramelessWindowHint));QVERIFY(welcome.windowFlags().testFlag(Qt::WindowStaysOnTopHint));QVERIFY(welcome.testAttribute(Qt::WA_TranslucentBackground));welcome.show();QCoreApplication::processEvents();QVERIFY(welcome.mask().isEmpty());const QImage rendered=welcome.grab().toImage().convertToFormat(QImage::Format_ARGB32);QCOMPARE(qAlpha(rendered.pixel(0,0)),0);QCOMPARE(qAlpha(rendered.pixel(rendered.width()-1,0)),0);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(welcome.grab().save(QStringLiteral("artifacts/e2e-welcome.png")));auto *hide=welcome.findChild<QCheckBox*>(QStringLiteral("welcome-hide"));auto *done=welcome.findChild<QPushButton*>(QStringLiteral("welcome-done"));QVERIFY(hide);QVERIFY(done);hide->setChecked(true);done->click();QVERIFY(!controller.settings().showWelcome);AppSettings saved=SettingsStore(path).load();QVERIFY(!saved.showWelcome);QVERIFY(saved.trayDiscoveryShown);controller.shutdown();}

