void E2ETests::wheelOverSliderScrollsPanelOnly(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("s.ini"))));controller.initialize();controller.setEink(QStringLiteral("fake-external"),true);MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();auto *saturation=panel.findChild<QSlider*>(QStringLiteral("saturation-slider"));auto *area=panel.findChild<QScrollArea*>();QVERIFY(saturation);QVERIFY(area);auto *bar=area->verticalScrollBar();bar->setValue(0);const int sliderBefore=saturation->value();const QPointF local=saturation->rect().center();const QPointF global=saturation->mapToGlobal(local.toPoint());QWheelEvent wheel(local,global,QPoint(),QPoint(0,-120),Qt::NoButton,Qt::NoModifier,Qt::NoScrollPhase,false);QApplication::sendEvent(saturation,&wheel);QCoreApplication::processEvents();QCOMPARE(saturation->value(),sliderBefore);QVERIFY(bar->value()>0);controller.shutdown();}

void E2ETests::minimizeAndFocusLossHidePanel(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("s.ini"))));controller.initialize();MainPanel panel(&controller);QSignalSpy quitSpy(&panel,&MainPanel::quitRequested);panel.show();QCoreApplication::processEvents();auto *minimize=panel.findChild<QPushButton*>(QStringLiteral("minimize-button"));auto *quit=panel.findChild<QPushButton*>(QStringLiteral("quit-button"));QVERIFY(minimize);QVERIFY(quit);QCOMPARE(minimize->text(),QStringLiteral("−"));QVERIFY(minimize->x()<quit->x());minimize->click();QVERIFY(!panel.isVisible());QCOMPARE(quitSpy.count(),0);panel.show();QCoreApplication::processEvents();panel.setConfigurationBusy(true);QEvent busyDeactivated(QEvent::WindowDeactivate);QApplication::sendEvent(&panel,&busyDeactivated);QTest::qWait(80);QVERIFY(panel.isVisible());panel.setConfigurationBusy(false);auto *languages=panel.findChild<QComboBox*>(QStringLiteral("language-combo"));QVERIFY(languages);languages->showPopup();QTRY_VERIFY(QApplication::activePopupWidget());QEvent popupDeactivated(QEvent::WindowDeactivate);QApplication::sendEvent(&panel,&popupDeactivated);QTest::qWait(80);QVERIFY(panel.isVisible());languages->hidePopup();QCoreApplication::processEvents();QApplication::setActiveWindow(nullptr);QEvent deactivated(QEvent::WindowDeactivate);QApplication::sendEvent(&panel,&deactivated);QTRY_VERIFY(!panel.isVisible());QCOMPARE(quitSpy.count(),0);controller.shutdown();}

void E2ETests::cjkLanguagesUseWindowsUiFonts(){
    if(QGuiApplication::platformName()==QStringLiteral("offscreen"))QSKIP("The offscreen Qt plugin does not enumerate Windows system fonts.");
    QString baseStyle=QApplication::style()->objectName();if(baseStyle.isEmpty())baseStyle=QStringLiteral("windowsvista");QApplication::setStyle(new ui::SmoothProxyStyle(baseStyle));
    Localization::instance().setLanguage(QStringLiteral("zh-Hans"));QVERIFY(QApplication::font().family()==QStringLiteral("Microsoft YaHei UI")||QApplication::font().family()==QStringLiteral("Microsoft YaHei"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    Localization::instance().setLanguage(QStringLiteral("zh-Hant"));QVERIFY(QApplication::font().family()==QStringLiteral("Microsoft JhengHei UI")||QApplication::font().family()==QStringLiteral("Microsoft JhengHei"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    Localization::instance().setLanguage(QStringLiteral("ja"));QVERIFY(QApplication::font().family()==QStringLiteral("Yu Gothic UI")||QApplication::font().family()==QStringLiteral("Meiryo UI")||QApplication::font().family()==QStringLiteral("Meiryo"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    QVERIFY((QApplication::font().styleStrategy()&QFont::PreferAntialias)!=0);QCOMPARE(QApplication::font().hintingPreference(),QFont::PreferNoHinting);
    Localization::instance().setLanguage(QStringLiteral("en"));QCOMPARE(QApplication::font().family(),QStringLiteral("Segoe UI"));QCOMPARE(QFontInfo(QApplication::font()).family(),QApplication::font().family());
    auto capture=[](const QString &language,const QString &fileName){QTemporaryDir dir;const QString path=dir.filePath(QStringLiteral("language.ini"));AppSettings settings;settings.language=language;SettingsStore(path).save(settings);auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();QDir().mkpath(QStringLiteral("artifacts"));const bool saved=panel.grab().save(QStringLiteral("artifacts/")+fileName);controller.shutdown();return saved;};
    QVERIFY(capture(QStringLiteral("zh-Hans"),QStringLiteral("e2e-cjk.png")));QVERIFY(capture(QStringLiteral("zh-Hant"),QStringLiteral("e2e-zh-Hant.png")));QVERIFY(capture(QStringLiteral("ja"),QStringLiteral("e2e-ja.png")));
    Localization::instance().setLanguage(QStringLiteral("en"));
}

void E2ETests::busyIndicatorAnimates(){BusyDialog busy;busy.setMessage(L("busy.configuring"));busy.showCentered();QCoreApplication::processEvents();auto *spinner=busy.findChild<QWidget*>(QStringLiteral("busy-spinner"));auto *message=busy.findChild<QLabel*>(QStringLiteral("busy-message"));QVERIFY(spinner);QVERIFY(message);QCOMPARE(message->text(),L("busy.configuring"));QVERIFY(busy.testAttribute(Qt::WA_TranslucentBackground));QVERIFY(busy.mask().isEmpty());const QImage rendered=busy.grab().toImage().convertToFormat(QImage::Format_ARGB32);QCOMPARE(qAlpha(rendered.pixel(0,0)),0);QVERIFY(qAlpha(rendered.pixel(rendered.width()/2,rendered.height()/2))>250);const int before=spinner->property("angle").toInt();QTest::qWait(180);QVERIFY(spinner->property("angle").toInt()!=before);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(busy.grab().save(QStringLiteral("artifacts/e2e-configuring.png")));busy.hide();}

void E2ETests::hotplugThenOpenPanelIsStable(){QTemporaryDir dir;const QString path=dir.filePath(QStringLiteral("hotplug.ini"));auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();const DisplayInfo external=raw->displayList.front();raw->displayList.removeFirst();AppSettings settings;auto &externalSettings=settings.forDisplay(external.stableId);externalSettings.isEink=true;externalSettings.saturation=1.3;SettingsStore(path).save(settings);ApplicationController controller(std::move(fake),SettingsStore(path));controller.initialize();MainPanel panel(&controller);for(int i=0;i<20;++i){if(i%2==0)raw->displayList.prepend(external);else raw->displayList.removeFirst();controller.refreshDisplays();}raw->displayList.prepend(external);controller.refreshDisplays();controller.reapplyAll();QCoreApplication::processEvents();panel.showPanel();QCoreApplication::processEvents();int matches=0;for(QCheckBox *box:panel.findChildren<QCheckBox*>(QStringLiteral("eink-checkbox")))if(box->property("displayId").toString()==external.stableId)++matches;QCOMPARE(matches,1);QCOMPARE(controller.displays().size(),2);QTRY_VERIFY(raw->colorApplyCalls>0);controller.shutdown();}

void E2ETests::trayUsesBookPagesGlyph(){
    const QImage light=ui::bookPagesTrayImage(48,true).convertToFormat(QImage::Format_ARGB32);
    const QImage dark=ui::bookPagesTrayImage(48,false).convertToFormat(QImage::Format_ARGB32);
    int blackPixels=0,whitePixels=0;
    for(int y=0;y<48;++y)for(int x=0;x<48;++x){const QRgb a=light.pixel(x,y),b=dark.pixel(x,y);if(qAlpha(a)>160&&qGray(a)<64)++blackPixels;if(qAlpha(b)>160&&qGray(b)>192)++whitePixels;}
    QVERIFY(blackPixels>100);QVERIFY(whitePixels>100);QCOMPARE(qAlpha(light.pixel(0,0)),0);QCOMPARE(qAlpha(dark.pixel(47,47)),0);
    QImage preview(128,64,QImage::Format_ARGB32);preview.fill(Qt::white);QPainter painter(&preview);painter.fillRect(64,0,64,64,QColor(32,32,32));painter.drawImage(8,8,light);painter.drawImage(72,8,dark);painter.end();QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(preview.save(QStringLiteral("artifacts/e2e-tray-book-pages.png")));
}

void E2ETests::windows10TrayPromotionFindsOwnIcon(){
#ifdef Q_OS_WIN
    if(QGuiApplication::platformName()!=QStringLiteral("windows"))QSKIP("A real Windows notification area is required.");
    if(!QSystemTrayIcon::isSystemTrayAvailable())QSKIP("The Windows notification area is unavailable.");
    QSystemTrayIcon tray(ui::bookPagesTrayIcon(ui::systemTrayUsesLightBackground()));
    tray.setToolTip(QStringLiteral("E-Ink Assistant Windows 10 tray compatibility test"));
    tray.show();
    windows::TrayPromotionResult result=windows::TrayPromotionResult::Pending;
    for(int attempt=0;attempt<12&&result==windows::TrayPromotionResult::Pending;++attempt){QTest::qWait(150);result=windows::promoteOwnTrayIcon();}
    qInfo().noquote()<<windows::trayIntegrationDiagnostic();
    QVERIFY(result==windows::TrayPromotionResult::Promoted||result==windows::TrayPromotionResult::Overflow);
    if(result==windows::TrayPromotionResult::Promoted)QTRY_VERIFY_WITH_TIMEOUT(!windows::ownPromotedTrayIconRects().isEmpty(),2000);
    else QVERIFY(windows::ownTrayIconInOverflow());
    tray.hide();
#else
    QSKIP("Windows-only tray test.");
#endif
}

void E2ETests::processingIndicatorStaysInsideMainWindow(){
    QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("busy.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();panel.setConfigurationBusy(true,L("busy.configuring"));QCoreApplication::processEvents();
    auto *indicator=panel.findChild<QWidget*>(QStringLiteral("inline-processing"));auto *message=panel.findChild<QLabel*>(QStringLiteral("inline-processing-message"));auto *spinner=panel.findChild<QWidget*>(QStringLiteral("inline-processing-spinner"));QVERIFY(indicator);QVERIFY(message);QVERIFY(spinner);QVERIFY(indicator->isVisible());QCOMPARE(indicator->window(),static_cast<QWidget*>(&panel));QCOMPARE(message->text(),L("busy.configuring"));QCOMPARE(panel.cursor().shape(),Qt::ArrowCursor);
    for(QWidget *top:QApplication::topLevelWidgets())QVERIFY2(!(top->objectName()==QStringLiteral("busy-dialog")&&top->isVisible()),"Configuration opened a separate busy window");
    const QImage indicatorImage=indicator->grab().toImage().convertToFormat(QImage::Format_ARGB32);const QPoint clearSample=spinner->mapTo(indicator,QPoint(1,1));const QColor clearColor=indicatorImage.pixelColor(clearSample);QVERIFY2(clearColor.red()>=235&&clearColor.red()<252&&clearColor.red()==clearColor.green()&&clearColor.green()==clearColor.blue(),qPrintable(QStringLiteral("Spinner corner was not transparent over the processing pill: %1").arg(clearColor.name())));
    const int before=spinner->property("angle").toInt();QTest::qWait(180);QVERIFY(spinner->property("angle").toInt()!=before);QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-inline-processing.png")));panel.setConfigurationBusy(false);QVERIFY(!indicator->isVisible());controller.shutdown();
}

