void E2ETests::firstShowBindsToRequestedScreen(){
    const auto screens=QGuiApplication::screens();if(screens.size()<2)QSKIP("Mixed-monitor placement requires at least two active screens.");
    QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("placement.ini"))));controller.initialize();MainPanel panel(&controller);
    QScreen *first=screens.first();QScreen *second=screens.last();panel.showPanel(first);QTRY_COMPARE(panel.windowHandle()->screen(),first);QVERIFY(first->availableGeometry().contains(panel.frameGeometry().center()));panel.hide();QCoreApplication::processEvents();
    panel.showPanel(second);QTRY_COMPARE(panel.windowHandle()->screen(),second);QTest::qWait(120);const QRect panelRect=panel.frameGeometry(),targetRect=second->availableGeometry();QVERIFY2(targetRect.contains(panelRect.center()),qPrintable(QStringLiteral("Panel center %1,%2 was outside %3 on %4 (DPR %5)").arg(panelRect.center().x()).arg(panelRect.center().y()).arg(second->name()).arg(targetRect.width()).arg(second->devicePixelRatio())));panel.hide();controller.shutdown();
}

void E2ETests::widerLayoutKeepsLabelsVisible(){
    if(QGuiApplication::platformName()==QStringLiteral("offscreen"))QSKIP("Native font metrics and size-hint propagation are required for clipping checks.");Localization::instance().setLanguage(QStringLiteral("en"));QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("wide.ini"))));controller.initialize();controller.settingsFor(QStringLiteral("fake-external")).isEink=true;MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();QCOMPARE(panel.width(),680);
    QLabel *visualTitle=nullptr;for(QLabel *candidate:panel.findChildren<QLabel*>())if(candidate->text()==L("system.title")){visualTitle=candidate;break;}QVERIFY(visualTitle);const QFontMetrics titleMetrics(visualTitle->font());QVERIFY2(!visualTitle->wordWrap(),"Reduce Transparency & Motion was still configured to wrap");QVERIFY2(titleMetrics.horizontalAdvance(visualTitle->text())<=visualTitle->width(),"Reduce Transparency & Motion was horizontally clipped");
    auto *factory=panel.findChild<QPushButton*>(QStringLiteral("preset-factory"));QVERIFY(factory);factory->click();QCoreApplication::processEvents();QVERIFY(factory->isChecked());QCOMPARE(factory->property("selected-font-weight").toInt(),static_cast<int>(QFont::Black));QFont checkedFont=factory->font();checkedFont.setWeight(QFont::Black);QVERIFY2(QFontMetrics(checkedFont).horizontalAdvance(factory->text())+24<=factory->width(),"Heavy Factory label was clipped");QVERIFY2(!panel.findChild<QPushButton*>(QStringLiteral("visual-effects-settings")),"Reduce Transparency & Motion still exposed an unnecessary settings button");for(const char *name:{"preset-bw","preset-faded","preset-factory","preset-enhanced","preset-vivid","preset-anime"}){auto *button=panel.findChild<QPushButton*>(QString::fromLatin1(name));QVERIFY(button);QVERIFY(button->mapTo(&panel,QPoint(button->width(),0)).x()<=panel.width()-16);}QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-wide-layout.png")));controller.shutdown();
}

void E2ETests::modeButtonsAreContinuousAndPanelUsesScreenHeight(){
    if(QGuiApplication::platformName()==QStringLiteral("offscreen"))QSKIP("Native size-hint propagation is required for content-aware window height checks.");QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("height.ini"))));controller.initialize();controller.settingsFor(QStringLiteral("fake-external")).isEink=true;MainPanel panel(&controller);QScreen *screen=QGuiApplication::primaryScreen();QVERIFY(screen);panel.showPanel(screen);QCoreApplication::processEvents();const QRect available=screen->availableGeometry();QCOMPARE(panel.height(),available.height()-32);QCOMPARE(panel.frameGeometry().top()-available.top(),16);QCOMPARE(available.bottom()-panel.frameGeometry().bottom(),16);
    auto continuous=[&panel](const char *leftName,const char *rightName){auto *left=panel.findChild<QPushButton*>(QString::fromLatin1(leftName));auto *right=panel.findChild<QPushButton*>(QString::fromLatin1(rightName));QVERIFY(left);QVERIFY(right);const int leftRight=left->mapTo(&panel,QPoint(left->width(),0)).x();const int rightLeft=right->mapTo(&panel,QPoint(0,0)).x();QCOMPARE(rightLeft-leftRight,0);QCOMPARE(left->height(),right->height());QVERIFY(left->property("choice-button").toBool());QVERIFY(right->property("choice-button").toBool());};continuous("text-off","text-medium");continuous("text-medium","text-strong");continuous("video-off","video-subtle");continuous("video-subtle","video-medium");
    auto *selected=panel.findChild<QPushButton*>(QStringLiteral("text-off"));auto *unselected=panel.findChild<QPushButton*>(QStringLiteral("text-medium"));QVERIFY(selected&&selected->isChecked());QVERIFY(unselected&&!unselected->isChecked());QCOMPARE(selected->property("selected-font-weight").toInt(),static_cast<int>(QFont::Black));
    auto darkBottomDepth=[](QPushButton *button){const QImage image=button->grab().toImage().convertToFormat(QImage::Format_ARGB32);const int x=image.width()/2;int depth=0;for(int y=image.height()-1;y>=0;--y){if(qGray(image.pixel(x,y))<100)++depth;else if(depth)break;}return depth;};
    QVERIFY2(darkBottomDepth(selected)>=darkBottomDepth(unselected)+2,"Selected segment did not use a distinct thick bottom underline");QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-continuous-mode-buttons.png")));panel.hide();controller.shutdown();
    auto compactFake=std::make_unique<FakePlatform>();compactFake->displayList.clear();ApplicationController compactController(std::move(compactFake),SettingsStore(dir.filePath(QStringLiteral("compact.ini"))));compactController.initialize();MainPanel compact(&compactController);compact.showPanel(screen);QCoreApplication::processEvents();QVERIFY2(compact.height()<available.height()-32,"A compact panel unnecessarily expanded to maximum screen height");QCOMPARE(available.bottom()-compact.frameGeometry().bottom(),16);compact.hide();compactController.shutdown();
}

void E2ETests::rgbDisclosureAndSwitchCornersUseVectorPainting(){
    QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("vector-controls.ini"))));controller.initialize();controller.settingsFor(QStringLiteral("fake-external")).isEink=true;MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();
    auto *rgb=panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle"));QVERIFY(rgb);QCOMPARE(rgb->text(),L("rgb.title"));QVERIFY(!rgb->text().contains(QChar(0x203A)));QVERIFY(!rgb->text().contains(QChar(0x2304)));QVERIFY(!rgb->property("disclosure-expanded").toBool());rgb->click();QCoreApplication::sendPostedEvents(nullptr,QEvent::DeferredDelete);QCoreApplication::processEvents();rgb=panel.findChild<QPushButton*>(QStringLiteral("rgb-toggle"));QVERIFY(rgb);QCOMPARE(rgb->text(),L("rgb.title"));QVERIFY(rgb->property("disclosure-expanded").toBool());
    auto *toggle=panel.findChild<QAbstractButton*>(QStringLiteral("advanced-switch"));QVERIFY(toggle);QVERIFY(toggle->property("antialiased-corners").toBool());const QImage image=toggle->grab().toImage().convertToFormat(QImage::Format_ARGB32);bool foundAntialiasedEdge=false;for(int y=0;y<image.height()&&!foundAntialiasedEdge;++y)for(int x=0;x<image.width();++x){const QColor pixel=image.pixelColor(x,y);if(pixel.red()==pixel.green()&&pixel.green()==pixel.blue()&&pixel.red()>40&&pixel.red()<240){foundAntialiasedEdge=true;break;}}QVERIFY2(foundAntialiasedEdge,"Switch outline did not contain antialiased edge pixels");
    QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-vector-controls.png")));controller.shutdown();
}

