void E2ETests::slowSystemTogglesUseLocalSpinner(){QTemporaryDir dir;auto fake=std::make_unique<FakePlatform>();FakePlatform *raw=fake.get();raw->systemDelayMs=350;ApplicationController controller(std::move(fake),SettingsStore(dir.filePath(QStringLiteral("slow-system.ini"))));controller.initialize();MainPanel panel(&controller);panel.show();QCoreApplication::processEvents();auto *visual=panel.findChild<QAbstractButton*>(QStringLiteral("visual-effects-switch"));auto *visualSpinner=panel.findChild<QWidget*>(QStringLiteral("visual-effects-spinner"));auto *visualStatus=panel.findChild<QLabel*>(QStringLiteral("visual-effects-status"));auto *light=panel.findChild<QAbstractButton*>(QStringLiteral("windows-light-mode-switch"));auto *lightSpinner=panel.findChild<QWidget*>(QStringLiteral("windows-light-mode-spinner"));auto *lightStatus=panel.findChild<QLabel*>(QStringLiteral("windows-light-mode-status"));auto *headerBusy=panel.findChild<QWidget*>(QStringLiteral("inline-processing"));QVERIFY(visual);QVERIFY(visualSpinner);QVERIFY(visualStatus);QVERIFY(light);QVERIFY(lightSpinner);QVERIFY(lightStatus);QVERIFY(headerBusy);QElapsedTimer timer;timer.start();visual->click();QCoreApplication::processEvents();QVERIFY2(timer.elapsed()<100,"Visual-effects click blocked the GUI thread.");QVERIFY(!visual->isVisible());QVERIFY(visualSpinner->isVisible());QVERIFY(!headerBusy->isVisible());QDir().mkpath(QStringLiteral("artifacts"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-local-system-spinner-active.png")));QTest::qWait(300);QVERIFY(!headerBusy->isVisible());QTRY_VERIFY_WITH_TIMEOUT(visual->isVisible(),1000);QVERIFY(!visualSpinner->isVisible());QVERIFY(raw->effectsReduced);QCOMPARE(visualStatus->text(),L("system.on"));timer.restart();light->click();QCoreApplication::processEvents();QVERIFY2(timer.elapsed()<100,"Windows-mode click blocked the GUI thread.");QVERIFY(!light->isVisible());QVERIFY(lightSpinner->isVisible());QVERIFY(!headerBusy->isVisible());QTRY_VERIFY_WITH_TIMEOUT(light->isVisible(),1000);QVERIFY(!lightSpinner->isVisible());QVERIFY(raw->lightMode);QCOMPARE(lightStatus->text(),L("system.on"));QVERIFY(panel.grab().save(QStringLiteral("artifacts/e2e-local-system-spinner.png")));controller.shutdown();}

